public partial class MainWindow:Window {
 readonly MainViewModel vm=new();string current="Dashboard";readonly Dictionary<string,List<KeyValuePair<string,string>>> lookups=[];
 public MainWindow(){InitializeComponent();MaxHeight=SystemParameters.WorkArea.Height;Height=Math.Min(Height,MaxHeight);WindowStartupLocation=WindowStartupLocation.CenterScreen;DataContext=vm;ApiAddress.Text=MainViewModel.SavedAddress();}
 async void Login(object sender,RoutedEventArgs e){if(connectionBusy)return;if(string.IsNullOrWhiteSpace(ApiAddress.Text)){LoginStatus.Text="Click Find server or open its connection file first.";return;}ConnectionBusy(true);LoginStatus.Text="Connecting…";try{await vm.Login(ApiAddress.Text,Email.Text,Password.Password);Password.Clear();LoginPanel.Visibility=Visibility.Collapsed;Navigation.SelectedIndex=0;}catch(Exception ex){LoginStatus.Text=ex.Message;}finally{ConnectionBusy(false);}}
 void SignOut(object sender,RoutedEventArgs e){vm.Client.DefaultRequestHeaders.Authorization=null;vm.Rows=null;LoginPanel.Visibility=Visibility.Visible;Password.Clear();LoginStatus.Text="Signed out. Session tokens are kept only in memory.";}
 async void Navigate(object sender,SelectionChangedEventArgs e){if(Navigation.SelectedItem is string page){current=page;await LoadPage();}}
 async void Refresh(object sender,RoutedEventArgs e)=>await LoadPage();
 async Task Guard(Func<Task> action){try{await action();}catch(Exception ex){vm.Status=ex is System.Net.Http.HttpRequestException or TaskCanceledException?"Connection unavailable. Transaction outcome may be uncertain. Refresh reports and reconcile before submitting again.":ex.Message;}}
 void Button(string title,Func<Task> action){var b=new Button{Content=title};b.Click+=async(s,e)=>await Guard(action);Toolbar.Children.Add(b);}
 async Task LoadPage()=>await Guard(async()=>{
  vm.Title=current;Toolbar.Children.Clear();Summary.Visibility=Visibility.Collapsed;MetricCards.Children.Clear();Table.Visibility=Visibility.Visible;
  var endpoint=current switch{"Dashboard"=>"dashboard","Medicine Master"=>"medicines","Barcode Registration"=>"barcodes","Inventory Receiving"=>"receiving","Inventory Management"=>"inventory","Medication Dispensing"=>"orders","Stock Transfers"=>"transfers","Returns and Adjustments"=>"counts","Expiration Monitoring"=>"reports/near-expiry","Medicine Recalls"=>"recalls","Cerebro Synchronization"=>"integration","Reports"=>"reports/inventory","Scanner Settings"=>"scanners","Workstation Management"=>"workstations","User Administration"=>"users","Audit Logs"=>"audit","System Settings"=>"settings",_=>""};
  if(current=="About Application"){
   Table.Visibility=Visibility.Collapsed;Summary.Visibility=Visibility.Visible;SummaryText.Text="DDHI Smart Pharmacy Barcode Manager\n\nDigos Doctors Hospital, Inc.\nHospital Pharmacy Inventory and Barcode Management System\n\nDeveloper: Vicente C. Cavalida Jr. MD\nVersion: 0.2.0 • Build: "+File.GetLastWriteTime(Environment.ProcessPath!).ToString("yyyy-MM-dd")+"\nCopyright © 2026 Digos Doctors Hospital, Inc.\nLicense: Hospital evaluation; see LICENSE.txt.\n\nPilot build. Hospital acceptance and authorized production deployment required.";return;
  }
  if(current=="Scan Medicine"){
   vm.Rows=null;Button("Scan / enter barcode",Scan);Button("Decode barcode image",DecodeImage);Button("Read COM barcode",ReadCom);Button("COM diagnostic",ComDiagnostic);vm.Status="HID and manual input are unverified. Scanning never completes a transaction. No scanner is required.";return;
  }
  if(endpoint!="")await vm.Load(endpoint);
  switch(current){
   case "Dashboard":Table.Visibility=Visibility.Collapsed;var metrics=await vm.Get("dashboard");foreach(var item in metrics.EnumerateObject().Where(x=>x.Value.ValueKind==JsonValueKind.Number)){var stack=new StackPanel{Margin=new Thickness(14)};stack.Children.Add(new TextBlock{Text=item.Value.ToString(),FontSize=34,FontWeight=FontWeights.SemiBold,Foreground=new SolidColorBrush(Color.FromRgb(8,123,88))});stack.Children.Add(new TextBlock{Text=System.Text.RegularExpressions.Regex.Replace(item.Name,"([A-Z])"," $1").ToUpperInvariant(),FontSize=11,TextWrapping=TextWrapping.Wrap});MetricCards.Children.Add(new Border{Background=new SolidColorBrush(Color.FromRgb(241,247,244)),Margin=new Thickness(5),Child=stack});}Summary.Visibility=Visibility.Visible;SummaryText.Text="One central inventory. Every movement traceable.\nReview near-expiry stock, recalls and reconciliation before dispensing.";break;
   case "Medicine Master":Button("Set active status",()=>Form("medicines/"+SelectedId()+"/status","Medicine status",[new("activeStatus","Active","bool","true"),new("reason","Authorized reason")]));Button("Import approved CSV",ImportMedicines);Button("Add medicine",()=>Form("medicines","New medicine",[new("genericName","Generic name"),new("brandName","Brand name"),new("strength","Strength"),new("dosageForm","Dosage form"),new("route","Route"),new("manufacturer","Manufacturer"),new("category","Category"),new("baseUnit","Base unit","text","unit"),new("reorderLevel","Reorder level","number","0")]));break;
   case "Barcode Registration":Button("Register barcode",()=>Form("barcodes","Approve barcode mapping",[new("medicineId","Medicine",Lookup:"medicines"),new("barcode","Barcode"),new("packaging","Packaging","text","unit"),new("conversionFactor","Base units per package","number","1")]));break;
   case "Inventory Receiving":Button("Receive stock",()=>Form("receiving","Confirm delivery line",[new("medicineId","Medicine",Lookup:"medicines"),new("supplierId","Supplier",Lookup:"suppliers"),new("locationId","Location",Lookup:"locations"),new("reference","Unique delivery-line reference"),new("lot","Batch / lot"),new("expiration","Approved expiration date","date"),new("quantity","Packages received","number","1"),new("conversionFactor","Base units per package","number","1"),new("unitCost","Cost per base unit","number","0")]));Button("Add supplier",()=>Form("suppliers","New supplier",[new("name","Supplier name")]));break;
   case "Inventory Management":Button("Quarantine / release stock",()=>Form("stock-status","Approved stock status transition",[new("balanceId","Stock balance",Lookup:"inventory"),new("targetStatus","Target status","choice","Quarantined|Damaged|PendingVerification|Available"),new("quantity","Base units","number","1"),new("reference","Transaction reference"),new("approvalReference","Hospital approval / quality-review reference")]));Button("Record disposition",()=>Form("disposals","Authorized physical disposition",[new("balanceId","Stock balance",Lookup:"inventory"),new("quantity","Base units","number","1"),new("reference","Disposal / supplier-return reference"),new("reason","Authorized physical-disposition reason")]));Button("Print stock label",PrintStockLabel);Button("Add location",()=>Form("locations","New location",[new("name","Location name")]));Button("Reconcile ledger",async()=>{await vm.Post("reconciliation",new{});await vm.Load("reconciliation");});Button("FEFO by medicine",Fefo);break;
   case "Medication Dispensing":
    Button("Record authorized order",()=>Form("orders","Authorized order reference",[new("reference","Authorized order reference"),new("encounterReference","Minimal patient / encounter reference"),new("medicineId","Prescribed medicine, strength and form",Lookup:"medicines"),new("quantity","Ordered base units","number","1")]));
    Button("Verify and dispense",()=>Form("dispensing","Pharmacist verification",[new("orderId","Authorized order",Lookup:"orders"),new("balanceId","Exact stock batch",Lookup:"inventory"),new("quantity","Base units to dispense","number","1"),new("verificationMode","Verification method","choice","ManualSelection|ManualBarcode|HidUnverified"),new("barcode","Barcode (blank for manual selection)"),new("patientVerified","I verified patient identity","bool"),new("overrideReason","Approved manual verification reason")]));
    Button("Reserve stock",()=>Form("reservations","15-minute reservation",[new("orderId","Order",Lookup:"orders"),new("balanceId","Stock batch",Lookup:"inventory"),new("quantity","Base units","number","1")]));break;
   case "Stock Transfers":Button("Transfer stock",()=>Form("transfers","Stock transfer",[new("balanceId","Source stock",Lookup:"inventory"),new("destinationId","Destination",Lookup:"locations"),new("quantity","Base units","number","1"),new("reference","Reference"),new("reason","Reason")]));break;
   case "Returns and Adjustments":Button("Reverse a stock movement",()=>Form("movements/"+SelectedId()+"/reverse","Reverse selected stock movement",[new("reason","Authorized correction reason")]));Button("View movements",()=>vm.Load("movements"));Button("Count / adjust",()=>Form("counts","Authorized stock count",[new("balanceId","Stock batch",Lookup:"inventory"),new("countedQuantity","Counted base units","number","0"),new("reference","Count reference"),new("reason","Authorized reason")]));Button("Return to quarantine",()=>Form("returns","Return dispensed medicine",[new("dispenseLineId","Dispense line",Lookup:"reports/dispensing"),new("quantity","Returned base units","number","1"),new("reference","Return reference"),new("reason","Reason")]));break;
   case "Expiration Monitoring":foreach(var days in new[]{180,90,60,30}){var d=days;Button($"Within {d} days",async()=>{await vm.Load("reports/near-expiry");if(vm.Rows!=null){var end=DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(8)).Date.AddDays(d).ToString("yyyy-MM-dd");vm.Rows.RowFilter=$"Expiration <= '{end}'";}});}Button("Expired",()=>vm.Load("reports/expired"));break;
   case "Medicine Recalls":Button("Close selected recall",()=>Form("recalls/"+SelectedValue("recallId")+"/close","Recall closure",[new("reason","Authorized closure reason (affected stock must be zero)")]));Button("Register and block batch",()=>Form("recalls","Recall notice",[new("batchId","Batch",Lookup:"batches"),new("reference","Recall notice reference"),new("reason","Recall reason")]));break;
   case "Cerebro Synchronization":Button("Test mock adapter",async()=>{var result=await vm.Post("integration/test",new{});vm.SetRows(result);});Button("Manual acknowledgment",()=>Form("integration/"+SelectedId()+"/acknowledge","Confirm external posting",[new("reference","Verified external acknowledgment reference")]));break;
   case "Reports":foreach(var report in new[]{"inventory","low-stock","near-expiry","expired","valuation","receiving","dispensing","movements","traceability","adjustments","recalls","integration","failed-transactions","reconciliation","user-activity"}){var r=report;Button(r,()=>vm.Load("reports/"+r));}break;
   case "Scanner Settings":Button("Edit selected profile",EditScanner);Button("Add scanner profile",()=>Form("scanners","Optional scanner configuration",[new("workstationId","Workstation",Lookup:"workstations"),new("name","Scanner name"),new("enabled","Enable profile","bool","true"),new("type","Scanner type","choice","HID|COM|Bluetooth HID|Vendor SDK"),new("port","COM port (if applicable)"),new("suffix","Input suffix","text","Enter")]));Button("COM diagnostic",ComDiagnostic);vm.Status="Profiles configure zero-to-many scanners. HID device connection is not detected. Vendor SDK is an extension boundary.";break;
   case "Workstation Management":Button("Register workstation",()=>Form("workstations","Workstation identity",[new("name","Unique workstation name")]));break;
   case "User Administration":Button("Lock / unlock account",()=>Form("users/"+SelectedId()+"/lock","Staff account access",[new("locked","Lock account","bool","true"),new("reason","Authorized reason")]));Button("Create individual account",()=>Form("users","Staff account",[new("email","Staff email"),new("password","Temporary password (12+ characters)","password"),new("role","Role","choice","Read-Only User|Inventory Clerk|Pharmacy Assistant|Pharmacist|Chief Pharmacist|Pharmacy Administrator|Auditor|System Administrator")]));break;
   case "Audit Logs":Button("Verify hash chain",async()=>{vm.SetRows(await vm.Get("audit/verify"));});break;
   case "System Settings":Button("Manual dispensing policy",()=>Form("settings","Chief Pharmacist policy approval",[new("name","Setting","text","ManualDispensingApproved"),new("value","Enabled","choice","false|true"),new("approvalReference","Written hospital approval reference")]));break;
  }
  if(current is "Reports" or "Audit Logs" or "Inventory Management" or "Expiration Monitoring"){Button("Export CSV / Excel",Export);Button("Print / PDF",Print);}
 });

 string SelectedValue(string field){if(Table.SelectedItem is DataRowView row){foreach(DataColumn col in row.DataView.Table!.Columns)if(col.ColumnName.Equals(field,StringComparison.OrdinalIgnoreCase))return row[col.ColumnName].ToString()??"";}throw new InvalidOperationException("Select an appropriate record first.");}
 async Task EditScanner(){var id=SelectedId();var profile=(await vm.Get("scanners")).EnumerateArray().Single(x=>x.GetProperty("id").GetString()==id);var form=new FormWindow("Configure scanner profile",[new("enabled","Enable scanner profile","bool",profile.GetProperty("enabled").GetBoolean()?"true":"false"),new("name","Name","text",profile.GetProperty("name").GetString()!),new("type","Interface","choice",string.Join("|",new[]{profile.GetProperty("type").GetString()!}.Concat(new[]{"HID","COM","Bluetooth HID","Vendor SDK"}).Distinct())),new("port","COM port","text",profile.GetProperty("port").GetString()!),new("suffix","Suffix","text",profile.GetProperty("suffix").GetString()!)],lookups){Owner=this};if(form.ShowDialog()==true){form.Values["workstationId"]=profile.GetProperty("workstationId").GetString();await vm.Post("scanners/"+id+"/configure",form.Values);await LoadPage();}}
 string SelectedId(){if(Table.SelectedItem is DataRowView row){foreach(var key in new[]{"id","Id"})if(row.DataView.Table!.Columns.Contains(key))return row[key].ToString()!;}throw new InvalidOperationException("Select a record first.");}
 async Task FetchLookup(string key){if(lookups.ContainsKey(key))lookups.Remove(key);var endpoint=key=="batches"?"inventory":key;var rows=(await vm.Get(endpoint)).EnumerateArray();var list=new List<KeyValuePair<string,string>>();foreach(var r in rows){string Get(params string[] names){foreach(var n in names)foreach(var p in r.EnumerateObject())if(p.Name.Equals(n,StringComparison.OrdinalIgnoreCase))return p.Value.ToString();return "";}var id=Get(key=="batches"?"batchId":"id");var label=string.Join(" · ",new[]{Get("genericName","medicine","name","reference"),Get("strength"),Get("dosageForm"),Get("lot"),Get("expiration"),Get("location"),Get("quantity"),id}.Where(x=>x!=""));list.Add(new(id,label));}lookups[key]=list.DistinctBy(x=>x.Key).ToList();}
 async Task Form(string endpoint,string title,Field[] fields){foreach(var key in fields.Where(x=>x.Lookup!=null).Select(x=>x.Lookup!).Distinct())await FetchLookup(key);var form=new FormWindow(title,fields,lookups){Owner=this};if(form.ShowDialog()==true){var result=await vm.Post(endpoint,form.Values);await LoadPage();vm.Status="Transaction committed centrally. Reference: "+result.ToString();}}

 async Task ImportMedicines(){var dialog=new OpenFileDialog{Filter="Approved medicine CSV|*.csv"};if(dialog.ShowDialog()!=true)return;var form=new FormWindow("Authorized catalog import",[new("approvalReference","Hospital approval reference")],lookups){Owner=this};if(form.ShowDialog()==true){var csv=await File.ReadAllTextAsync(dialog.FileName);var result=await vm.Post("imports/medicines",new{csv,approvalReference=form.Values["approvalReference"],confirmed=true});await LoadPage();vm.Status=result.ToString();}}
 async Task ReadCom(){var form=new FormWindow("Read from configured COM scanner",[new("port","COM port","text","COM3"),new("baud","Baud rate","number","9600")],lookups){Owner=this};if(form.ShowDialog()!=true)return;vm.Status="Waiting up to 15 seconds for serial input…";var raw=await Task.Run(()=>{using var port=new System.IO.Ports.SerialPort(form.Values["port"]!.ToString()!,Convert.ToInt32(form.Values["baud"])){ReadTimeout=15000,NewLine="\r"};port.Open();return port.ReadLine();});vm.SetRows(await vm.Post("scan",new{barcode=raw}));vm.Status="COM input captured. Device identity has not been clinically validated; dispensing still requires approved manual verification.";}

 async Task Scan(){var form=new FormWindow("Scan / manual barcode entry",[new("barcode","Barcode input — HID keystrokes are unverified")],lookups){Owner=this};if(form.ShowDialog()==true){var raw=form.Values["barcode"]?.ToString()??"";var parsed=BarcodeParser.Parse(raw);vm.SetRows(await vm.Post("scan",new{barcode=raw}));vm.Status=$"{parsed.Symbology} • No stock movement performed. Input is not verified physical provenance.";}}
 async Task DecodeImage(){var dialog=new OpenFileDialog{Filter="Barcode image|*.png;*.jpg;*.jpeg;*.bmp"};if(dialog.ShowDialog()!=true)return;var source=new BitmapImage(new Uri(dialog.FileName));var converted=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);var bytes=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(bytes,converted.PixelWidth*4,0);var result=new ZXing.BarcodeReaderGeneric().Decode(new ZXing.RGBLuminanceSource(bytes,converted.PixelWidth,converted.PixelHeight,ZXing.RGBLuminanceSource.BitmapFormat.BGRA32));if(result==null)throw new InvalidOperationException("No barcode decoded.");vm.SetRows(await vm.Post("scan",new{barcode=result.BarcodeFormat==ZXing.BarcodeFormat.CODE_128&&!result.Text.StartsWith("DDHI-")? "]C0"+result.Text:result.Text}));vm.Status="Image decoded. This is unverified image input, not a physical scan.";}
 Task ComDiagnostic(){var ports=System.IO.Ports.SerialPort.GetPortNames();vm.Status="Available serial ports: "+(ports.Length==0?"none":string.Join(", ",ports))+". A port's presence does not verify a scanner. Device read acceptance remains required.";return Task.CompletedTask;}
 async Task Fefo(){await FetchLookup("medicines");var f=new FormWindow("FEFO availability",[new("medicineId","Medicine",Lookup:"medicines")],lookups){Owner=this};if(f.ShowDialog()==true)await vm.Load("fefo/"+f.Values["medicineId"]);}
 Task Export(){if(vm.Rows==null)return Task.CompletedTask;var dialog=new SaveFileDialog{Filter="Excel-compatible CSV|*.csv",FileName="DDHI-"+current.Replace(' ','-')+".csv"};if(dialog.ShowDialog()==true){string Escape(string s){if(s.Length>0&&"=+-@\t\r".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}var lines=new List<string>{string.Join(",",vm.Rows.Table!.Columns.Cast<DataColumn>().Select(c=>Escape(c.ColumnName)))};foreach(DataRowView row in vm.Rows)lines.Add(string.Join(",",row.Row.ItemArray.Select(x=>Escape(x?.ToString()??""))));File.WriteAllLines(dialog.FileName,lines,new System.Text.UTF8Encoding(true));vm.Status="Export saved: "+dialog.FileName;}return Task.CompletedTask;}

 Task PrintStockLabel(){if(Table.SelectedItem is not DataRowView row)throw new InvalidOperationException("Select a stock balance first.");string Value(string name){foreach(DataColumn c in row.DataView.Table!.Columns)if(c.ColumnName.Equals(name,StringComparison.OrdinalIgnoreCase))return row[c.ColumnName].ToString()??"";return "";}
 var code="DDHI-STOCK-"+Guid.Parse(Value("Id")).ToString("N").ToUpperInvariant();var writer=new ZXing.BarcodeWriterPixelData{Format=ZXing.BarcodeFormat.CODE_128,Options=new ZXing.Common.EncodingOptions{Width=500,Height=100,Margin=10,PureBarcode=true}};var pixels=writer.Write(code);var bmp=BitmapSource.Create(pixels.Width,pixels.Height,96,96,PixelFormats.Bgra32,null,pixels.Pixels,pixels.Width*4);
 var doc=new FlowDocument{PagePadding=new Thickness(24),FontSize=12};doc.Blocks.Add(new Paragraph(new Run("Digos Doctors Hospital, Inc.\nINTERNAL STOCK LABEL")){FontSize=17,FontWeight=FontWeights.Bold});doc.Blocks.Add(new Paragraph(new Run(Value("Medicine")+" "+Value("Strength")+" "+Value("DosageForm")+"\nLot: "+Value("Lot")+"  Expiry: "+Value("Expiration")+"\nSource balance: "+Value("Id")+"\nBatch: "+Value("BatchId"))));doc.Blocks.Add(new BlockUIContainer(new Image{Source=bmp,Width=500,Height=100,Stretch=Stretch.Uniform}));doc.Blocks.Add(new Paragraph(new Run(code+"\nInternal traceability only. Review approved pharmacy labeling procedures.")));var dialog=new PrintDialog();if(dialog.ShowDialog()==true)dialog.PrintDocument(((IDocumentPaginatorSource)doc).DocumentPaginator,"DDHI stock label");return Task.CompletedTask;
 }

 Task Print(){if(vm.Rows==null)return Task.CompletedTask;var doc=new FlowDocument{PagePadding=new Thickness(40),FontSize=10};var image=new Image{Source=new BitmapImage(new Uri("pack://application:,,,/Assets/hospital-logo.png")),Width=70,Height=70,Stretch=Stretch.Uniform};doc.Blocks.Add(new BlockUIContainer(image));doc.Blocks.Add(new Paragraph(new Run("Digos Doctors Hospital, Inc.\n"+current+" • "+DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(8)).ToString("yyyy-MM-dd HH:mm zzz")+" Asia/Manila")){FontSize=18});foreach(DataRowView row in vm.Rows)doc.Blocks.Add(new Paragraph(new Run(string.Join("  |  ",vm.Rows.Table!.Columns.Cast<DataColumn>().Select(c=>c.ColumnName+": "+row[c.ColumnName])))));var dialog=new PrintDialog();if(dialog.ShowDialog()==true)dialog.PrintDocument(((IDocumentPaginatorSource)doc).DocumentPaginator,"DDHI "+current);return Task.CompletedTask;}
}
